// Récupérer les données du node précédent
const ibkrData = $input.first().json;

// Vérifier si les données existent
if (!ibkrData || !ibkrData.account) {
  throw new Error("Données IBKR manquantes");
}

// Formater le prompt pour Gemini
const prompt = `Tu es un expert en trading. Analyse ces données et donne un signal de trading.

COMPTE:
- NetLiquidation: ${ibkrData.account.NetLiquidation.value} ${ibkrData.account.NetLiquidation.currency}
- BuyingPower: ${ibkrData.account.BuyingPower.value} ${ibkrData.account.BuyingPower.currency}
- Cash: ${ibkrData.account.TotalCashValue.value} ${ibkrData.account.TotalCashValue.currency}

POSITIONS ACTUELLES:
${ibkrData.positions.map(p => `- ${p.symbol}: ${p.position} actions @ ${p.avgCost} EUR`).join('\n')}

TIMESTAMP: ${ibkrData.timestamp}

RÉPONDS UNIQUEMENT EN JSON (sans markdown, sans backticks):
{
  "signal": "BUY" | "SELL" | "HOLD",
  "confidence": 0-100,
  "reasoning": "courte explication",
  "symbol": "symbole à trader",
  "target_price": null ou float,
  "stop_loss": null ou float,
  "position_size": 0-100
}`;

return {
  prompt: prompt,
  ibkr_data: ibkrData
};

return items.map(item => {
  return {
    json: {
      prompt: item.json.prompt,
      ibkr_data: item.json.ibkr_data,
      gemini_body: {
        contents: [{
          parts: [{
            text: item.json.prompt
          }]
        }],
        generationConfig: {
          temperature: 0.3,
          topK: 40,
          topP: 0.95,
          maxOutputTokens: 500
        }
      }
    }
  };
});

// Récupère la réponse brute
const rawText = items[0].json.candidates[0].content.parts[0].text;

// Trouve le début et la fin du JSON (première '{' et dernière '}')
const firstBrace = rawText.indexOf('{');
const lastBrace = rawText.lastIndexOf('}');

let signalData;

if (firstBrace !== -1 && lastBrace !== -1) {
  // Extrait uniquement la partie JSON
  const jsonString = rawText.substring(firstBrace, lastBrace + 1);

  try {
    signalData = JSON.parse(jsonString);
  } catch (e) {
    signalData = { error: "Parsing failed despite cleanup", raw: jsonString };
  }
} else {
  signalData = { error: "No JSON found", raw: rawText };
}

return [{
  json: signalData
}];
